css:
.time-crystal-wrapper {
  --crystal-base-color: #4a4a4a;
  --crystal-panel-color: #333333;
  --crystal-glow-idle: rgba(52, 152, 219, 0.6);
  --crystal-glow-active: rgba(46, 204, 113, 0.8);
  --crystal-color-idle: #3498db;
  --crystal-color-active: #2ecc71;
  --text-color: #ecf0f1;
  --shadow-color: rgba(0, 0, 0, 0.5);
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100%;
  min-width: 100%;
  background: #212121;
  font-family: sans-serif;
  overflow: hidden;
}
.time-crystal-container {
  position: relative;
  width: 16em;
  height: 22em;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: flex-end;
}
.crystal-pedestal {
  width: 12em;
  height: 4em;
  background: linear-gradient(
    var(--crystal-panel-color),
    var(--crystal-base-color)
  );
  border-radius: 0.5em 0.5em 0 0;
  position: relative;
  box-shadow: 0 0.5em 0 #1a1a1a;
  border-top: 0.2em solid #555;
  border-left: 0.2em solid #555;
  border-right: 0.2em solid #555;
}
.crystal-pedestal-top {
  position: absolute;
  top: -1em;
  left: 1em;
  width: 10em;
  height: 1em;
  background: var(--crystal-base-color);
  border-radius: 0.2em;
  border: 0.2em solid #555;
}
.crystal-charge-checkbox {
  display: none;
}
.crystal-body {
  position: absolute;
  bottom: 6em;
  width: 8em;
  height: 10em;
  background: var(--crystal-color-idle);
  clip-path: polygon(50% 0%, 100% 35%, 85% 100%, 15% 100%, 0% 35%);
  z-index: 2;
  transition: all 0.5s ease;
  box-shadow: 0 0 2em var(--crystal-glow-idle);
}
.crystal-facet {
  position: absolute;
  width: 100%;
  height: 100%;
  background: rgba(255, 255, 255, 0.2);
  transition: all 0.5s ease;
}
.crystal-facet-1 {
  clip-path: polygon(50% 0%, 50% 50%, 0% 35%);
  animation: facet-flicker 4s infinite 0.5s;
}
.crystal-facet-2 {
  clip-path: polygon(50% 0%, 100% 35%, 50% 50%);
  animation: facet-flicker 4s infinite 1s;
}
.crystal-facet-3 {
  clip-path: polygon(50% 100%, 15% 100%, 50% 50%);
  animation: facet-flicker 4s infinite 1.5s;
}
.crystal-charge-checkbox:checked ~ .crystal-body {
  background: var(--crystal-color-active);
  box-shadow: 0 0 3em var(--crystal-glow-active);
  animation: crystal-pulse 2s infinite;
}
.crystal-charge-checkbox:checked ~ .crystal-body .crystal-facet {
  animation: facet-flicker-active 2s infinite;
}
.charge-switch-label {
  width: 6em;
  height: 2.5em;
  background: var(--crystal-panel-color);
  border-radius: 1.25em;
  cursor: pointer;
  position: absolute;
  bottom: 0.75em;
  box-shadow: inset 0 0.3em 0.5em var(--shadow-color);
}
.charge-switch-handle {
  width: 2em;
  height: 2em;
  background: var(--crystal-color-idle);
  border-radius: 50%;
  position: absolute;
  top: 0.25em;
  left: 0.25em;
  transition: all 0.4s cubic-bezier(0.68, -0.55, 0.27, 1.55);
  box-shadow: 0 0 1em var(--crystal-glow-idle);
}
.charge-switch-label:hover .charge-switch-handle {
  filter: brightness(1.2);
}
.crystal-charge-checkbox:checked ~ .charge-switch-label .charge-switch-handle {
  transform: translateX(3.5em);
  background: var(--crystal-color-active);
  box-shadow: 0 0 1em var(--crystal-glow-active);
}
@keyframes crystal-pulse {
  50% {
    transform: scale(1.05);
  }
}
@keyframes facet-flicker {
  50% {
    opacity: 0.5;
  }
}
@keyframes facet-flicker-active {
  50% {
    opacity: 0.8;
    transform: rotate(5deg) scale(0.9);
  }
}
